def add(title,body=None,formula=None,explain=None,result=None,limit=None,table=None,widths=None,chart=None,subtitle=None,notes='',sources=None,kind='standard'):
    slides.append(dict(title=title,body=body or [],formula=formula,explain=explain,result=result,limit=limit,table=table,widths=widths,chart=chart,subtitle=subtitle,notes=notes,sources=sources or [CURRENT,GUIDE],kind=kind))

def row(target,t=20,sigma=.0001,control='low',c=1.,plan='selected',profile='standard'):
    a=metrics[(metrics.target==target)&(metrics.total_s==t)&(metrics.residual_std_db==sigma)&(metrics.control==control)&(metrics.plan==plan)&(metrics.profile==profile)]
    if control=='low':a=a[a.concentration_ug_m3==c]
    assert len(a)==1
    return a.iloc[0]

add('Sub-THz atmospheric sensing',body=['What worked, how we achieved it, and what remains unresolved','Guillem Moreno Garcia\nUniversitat Politècnica de Catalunya\nSupervisor research review · 27 September 2026'],kind='cover',notes='This review describes the research snapshot at commit 461a3ba. Sensing performance remains conditional simulation. The original proposal contains eleven numbered subtasks.',sources=[AUDIT,'I2R_proposal_THz_ISAC (1).pdf'])
add('Problem statement',body=['Can a satellite communication downlink also detect gas and particle concentration changes using the same transmitted signal?','The proposal covers 60–400 GHz. Gas rotational lines provide spectral structure. Small particles produce a much smoother extinction signature.','The intended outcome combines useful recall, defensible concentration limits and an acceptable communication cost.'],formula='Observation = pollutant attenuation + atmospheric background + instrument error + noise',explain='The practical question is whether pollutant information survives the other unknowns.',limit='A correct forward model alone does not establish a useful environmental sensor.',sources=['I2R_proposal_THz_ISAC (1).pdf',AUDIT])
add('What we have achieved',table=[['Achievement','Evidence','Boundary'],['Physical model','Layered gas, particle, ray and thermal calculations','Conditional atmospheric and material assumptions'],['VOC detection','CH₃CN recall 97.67% at 1 µg/m³','20 s total and assumed 0.0001 dB residual'],['Engineering comparison','Sequential bands and moving coded-frame controls','RF specifications remain unmeasured'],['Failure diagnosis','PM information, gain drift and communication cost quantified','Useful joint VOC/PM retrieval remains open']],widths=[260,430,446],subtitle='A completed computational assessment with a conditional VOC improvement',limit='The 97.67% result uses the selected five-gas design with matched reference weather, 45° elevation, 23 dBm and 6 dB noise figure.',notes=BASE+'. 10,000 positive trials and 10,000 null trials. Exact recall interval 97.355–97.957%. Family false alarms 0.79%. All five gases and two PM masses remain unknown.',sources=[CURRENT,AUDIT])
add('The original eleven tasks',table=[['Task','Original requirement','Current outcome'],['1.1','Stratified atmosphere','Implemented with standard and measured weather'],['1.2','Spectroscopic inputs','Five target VOCs and traceable catalog gaps'],['1.3','Line shape and slant integration','Voigt profiles and refracted spherical paths'],['1.4','Particle extinction baseline','Rayleigh and Mie models, negative retrieval finding'],['2.1','Link and radio parameters','Explicit sequential receiver and resource budget'],['2.2','Simulated CSI','AWGN and bounded moving waveform controls'],['3.1','Spectral separation','Joint inference with nuisance projection'],['3.2','Concentration inversion','Payload moments and signed statistical estimates'],['4.1','Variance lower bounds','Nuisance-aware likelihood and Fisher bounds'],['4.2','Sensitivity','Common VOC/PM multivariable comparisons'],['4.3','Detection floors and standards','Conditional limits, no positive compliance claim']],widths=[110,395,631],notes='Each numbered task receives method and result slides. Task 3.2 lists statistical, optimization and ML methods as alternatives. A neural network is not a mandatory missing requirement.',sources=['I2R_proposal_THz_ISAC (1).pdf',AUDIT],kind='dense')
add('Evidence and operating conditions',table=[['Evidence','What it supports','What it cannot establish'],['HITRAN / ITU models','External physical parameters','Measured atmospheric radio performance'],['NOAA weather soundings','Actual weather profiles at selected times','Paired VOC/PM concentration truth'],['Monte Carlo responses','Conditional recall and concentration errors','Field recall under unknown model error'],['Raw coded OFDM frames','Bounded modem and synchronization checks','Full mission or continuous trajectory validation'],['Public water / calcite data','Limited independent physical checks','Calibrated joint VOC and PM retrieval']],widths=[265,400,471],limit='Every favorable result needs its time, calibration, concentration and receiver assumptions.',notes='Default current comparison: '+BASE+'. Calibration standard deviation denotes an additional differential spectral residual after reference subtraction. Zero residual is ideal. Nonzero residuals are also unmeasured assumptions.',sources=[PAPER,GUIDE])

add('Task 1.1 · Stratified atmosphere',body=['Implemented ITU-R P.835 reference layers through 100 km and NOAA IGRA measured weather profiles.','Interpolated temperature and log pressure / water vapor across height. Explicitly modeled the continuation above each sounding.'],formula='nₛ(z) = cₛ,₀ Nₐ / Mₛ · exp(−z/Hₛ)\nP(z), T(z), water(z) determine the local spectrum',explain='nₛ is molecular number density. Use consistent mass units for cₛ,₀ and molar mass Mₛ. Hₛ is an assumed concentration scale height.',result='The channel responds to vertical weather variation instead of using one homogeneous slab.',limit='The assumed pollutant profile does not become measured truth because the weather profile is measured.',sources=[PAPER,GUIDE,'src/thz_isac/atmosphere.py'])
add('Task 1.1 · Results and profile uncertainty',table=[['Component','Implemented result','Remaining uncertainty'],['Weather archive','103,322 levels from 521 soundings','Only selected dates enter sensing comparisons'],['Seasonal cases','January, April, July and September examples','Four profiles do not describe a population'],['Measured profile tops','28.8–37.0 km above the station','Upper continuation follows a model'],['Gas / PM scale height','1,500 m / 1,000 m','Unknown real pollutant distributions']],widths=[275,440,421],formula='c(z) = c₀ exp(−z/H)  ⇒  retrieved c₀ depends on H',explain='The reported concentration is a surface-equivalent enhancement under the chosen profile.',limit='Absolute ground concentration still requires baseline abundance and a validated column-to-surface mapping.',notes='The newest exact receiver comparison uses standard atmosphere and the existing January sounding. Older broader sensitivity studies include the other months. Do not imply that all four profiles enter the newest 288-condition grid.',sources=[PAPER,GUIDE])
add('Task 1.2 · Spectroscopic extraction',body=['Acquired line positions, strengths, pressure shifts, air broadening and temperature exponents from HITRAN.','Used isotope-specific masses and partition functions. Preserved line-source hashes and failed acquisition requests.'],formula='σₛ(ν,z) = Σℓ Sℓ(T(z)) Vℓ(ν − νℓ − δℓP(z))',explain='σₛ is molecular cross section. Sℓ is line strength and Vℓ is the normalized Voigt profile for local temperature and pressure.',result='The joint receiver now includes five organic gas targets and four interfering gases.',limit='HITRAN strengths already include natural isotope abundance. Applying it twice would understate absorption.',notes='Voigt Doppler width uses isotope mass. Reported mass concentration uses the natural-mixture molar mass. HCOOH rotational intensities involve dipole-based calculations and do not remove spectroscopy uncertainty.',sources=[GUIDE,'https://hitran.org/media/refs/HITRAN-2024.pdf','https://www.hitran.org/docs/molec-meta/'])
add('Task 1.2 · Every target gas and catalog gap',table=[['Target','Chemical identity','Current sensing result'],['H₂CO','Formaldehyde, an aldehyde','Weak recall at 1 µg/m³'],['CH₃OH','Methanol, an alcohol','Weak recall at 1 µg/m³'],['CH₃CN','Acetonitrile, a nitrile','Strongest low-concentration candidate'],['CH₃Cl','Chloromethane, a halogenated gas','Improves at higher concentration'],['HCOOH','Formic acid, a carboxylic acid','Largest current 95% concentration limit']],widths=[175,455,506],subtitle='CO, O₃, SO₂ and NO₂ enter as interferents. H₂O and O₂ enter the atmospheric background.',limit='CH₃Br, C₂H₄, CH₃F and CH₃I lack suitable lines in the acquired HITRAN window. This does not prove zero absorption.',notes='VOC is the project shorthand for these selected organic gases, not a universal regulatory classification. The retained coverage review uses HITRAN2024 Table 1, page 7. Additional candidates need usable microwave strengths and pressure broadening before quantitative inference.',sources=[GUIDE,'results/joint_receiver_revision/missing_spectroscopy_review.json'])
add('Task 1.3 · Voigt profiles and slant propagation',body=['Combined Doppler and pressure broadening at each atmospheric layer.','Integrated along a spherical refracted ray connecting receiver and satellite. Used atmospheric interfaces and numerical quadrature.'],formula='Aₛ(ν) = (10 / ln 10) ∫ray nₛ(z) σₛ(ν,z) ds\nPout / Pin = 10^(−A/10)       b = n(r) r sin ζ',explain='A is power attenuation in dB. b is the spherical ray invariant and ζ is the local zenith angle.',result='Elevation changes both the optical path and the received SNR.',limit='A secant factor applied after vertical integration cannot represent all refracted path effects.',sources=[PAPER,GUIDE])
add('Task 1.3 · Numerical convergence and thermal correction',table=[['Quantity','Relative RMS difference','Interpretation'],['Gas integration','0.00381%','Below the declared 0.1% numerical tolerance'],['PM integration','0.0225%','Below the declared tolerance'],['Atmospheric background','0.00200%','Below the declared tolerance'],['Thermal calculation, initial','0.11596%','Failed and triggered refinement'],['Thermal calculation, refined','0.00319%','Passed without relaxing the tolerance']],widths=[390,235,511],formula='Tsky = Σᵢ Jν(Tᵢ)(1 − e^(−τᵢ)) e^(−Σⱼ<ᵢ τⱼ) + transmitted space term',explain='Layer emission contributes receiver noise as well as attenuation.',limit='These are numerical checks on the tested grid. They do not measure atmospheric model error.',notes='An independent recursive transfer reproduced the refined brightness. Earlier seasonal weather calculations use order two and only September has its own separate order check. Current selected-tone calculations inherit declared quadrature. Do not claim convergence for every possible weather realization.',sources=[PAPER,'docs/45_payload_bounds_results.md'])
add('Task 1.4 · Rayleigh and Mie particle models',body=['Integrated spherical Mie extinction over truncated lognormal particle size distributions and normalized it by dry mass.','Converted aerodynamic size cuts to physical particle dimensions using the assumed density and shape model.'],formula='κext = ∫ Cext(r) p(r) dr / ∫ (4πρr³/3) p(r) dr\nRayleigh: κabs ≈ 3k Im(q)/ρ     κsca ≈ 2k⁴r³|q|²/ρ',explain='q = (m² − 1)/(m² + 2). k is wave number, m complex refractive index, ρ density and r sphere radius.',result='Rayleigh and full Mie agree closely in this particle-size and frequency regime.',limit='Material refractive index, shape, composition and humidity response remain assumptions.',sources=[GUIDE,PAPER])
add('Task 1.4 · PM definitions and the negative result',table=[['Output','Mass represented','Current result'],['PM1','Below 1 µm aerodynamic diameter','Exploratory extra split fails numerical separation'],['PM2.5','Fine mass below 2.5 µm','No useful mass retrieval in the tested grid'],['Coarse PM','Disjoint 2.5–10 µm mass','Nearly collinear with the fine-mode signature'],['PM10','Fine plus coarse mass','Includes their covariance, no valid 95% limit']],widths=[185,435,516],formula='Var(PM10) = Var(fine) + Var(coarse) + 2 Cov(fine, coarse)',explain='The fine model truncates below 0.03 µm. PM10 includes PM2.5, so they are not disjoint particle populations.',limit='A gain slope removes much of smooth Rayleigh absorption. Shared scattering shapes leave extremely weak size information.',notes='Fine assumptions: density 1500 kg/m³, median physical size 0.5 µm, geometric spread 1.7, refractive index 1.5 + 0.01i. Coarse: 1800 kg/m³, 4 µm, 1.6, 1.53 + 0.01i. Rayleigh/Mie RMS differences are 0.00086% fine and 0.0201% coarse in the earlier physical check. Three-bin scaled inverse identity error is approximately 0.508 and fails the gate.',sources=[GUIDE,'docs/48_expanded_voc_pm_and_20s_calibration.md'])
add('Task 2.1 · Link budget and sequential receiver',body=['Specified a 550 km downlink, 23 dBm active transmit power, 0.50 / 0.30 m apertures and a nominal 6 dB noise figure.','Replaced the ideal simultaneous broad reference with one RF chain hopping across sixteen 16 MHz blocks within 220–330 GHz.'],formula='Pr(ν) = Pt(ν) Gt(ν) Gr(ν) [λ/(4πR)]² 10^(−A(ν)/10) / Limpl\nSNR(ν) = Pr(ν) / {kB[Tsky(ν) + T₀(F − 1)]}',explain='R is range, F the linear noise factor and Limpl the linear implementation loss. Receiver noise figure enters once.',result='Each block has sixteen 1 MHz tones. CP, pilots, full frames, reference time and retuning all consume the time budget.',limit='23 dBm across the selected bands and 6 dB receiver noise are unverified RF requirements.',sources=[GUIDE,'docs/47_receiver_design_and_calibration.md'])
