add('Task 2.1 · Resources and communication cost',table=[['Quantity','Current result'],['Total reference + sample time','20 s, split equally'],['Actual frame transmission / retuning','19.72 s / 0.032 s'],['Instantaneous bandwidth / RF chains','16 MHz / one'],['Selected schedule Gaussian rate',f"{trade['candidate_gaussian_rate_bps']/1e6:.2f} Mbit/s"],['Best tested fixed block Gaussian rate',f"{trade['best_fixed_block_among_tested']['gaussian_fixed_rate_bps']/1e6:.2f} Mbit/s"],['Rate loss against that fixed block',f"{trade['gaussian_rate_loss_vs_best_tested_fixed_pct']:.2f}%"]],widths=[620,516],formula='Rate = time-weighted Σk Δf log₂(1 + SNRk)',explain='The comparison uses equal instantaneous bandwidth, power and CP/pilot overhead. Both reference and sample carry payload.',limit='Zero architecture cost is not established. Gaussian rate is different from coded QPSK throughput.',notes='Best fixed block among tested candidates is centered at 224 GHz. This is not a global optimum over every possible communications design. The older 1.382% number isolates schedule counts and must not replace the full 14.64% comparison.',sources=['results/joint_receiver_revision/communication_tradeoff.json',CURRENT])
