add('Task 3.1 · Joint spectral isolation',body=['Fitted all five gas signatures and two PM modes simultaneously.','Whitened the observation covariance and projected out gain offset/slope, atmospheric background and four interfering gases.'],formula='a = D c + N β + e       C = Cov(e)\nP = I − QN QNᵀ       ĉ = H a',explain='D contains target signatures. N contains nuisance signatures. QN spans the whitened nuisance space. An SVD constructs H.',result='Numerical gates check scaled H D ≈ I and nuisance rejection H N ≈ 0.',limit='No algorithm can separate an arbitrary gain error that occupies the same spectral direction as the pollutant.',sources=[GUIDE,'scripts/joint_receiver_support.py'])
