add('Task 4.1 · Lower bounds with nuisance parameters',body=['Derived full QPSK and magnitude likelihood information with unknown signal power, noise power and finite reference uncertainty.','Profiled nuisance parameters before comparing the attainable concentration covariance with the estimator variance.'],formula='Jab = E[(∂ log p(y;θ)/∂θa)(∂ log p(y;θ)/∂θb)]\nJeff = Jcc − Jcη Jηη⁻¹ Jηc       Cov(ĉ) ⪰ Jeff⁻¹',explain='c denotes target concentration and η all nuisance parameters. The Schur complement accounts for their uncertainty.',result='The bound identifies when replacing the estimator offers little remaining gain.',limit='The bound is local and conditional on the likelihood, covariance and physical signatures.',sources=['docs/44_payload_information_derivation.md','docs/45_payload_bounds_results.md'])
add('Task 4.1 · M2M4 is already close to the bound',table=[['Gas','CRLB / M2M4 variance','Historical 95% limit µg/m³'],['Formaldehyde','95.89%','4.456'],['Methanol','97.61%','10.307'],['Acetonitrile','96.49%','1.023']],widths=[345,400,391],subtitle='Historical broad reference, three target gases, 20 s total and zero extra calibration residual',formula='Efficiency = variance lower bound / estimator variance',explain='Values near 100% leave little improvement available from estimator replacement in this control.',result='The next substantial improvement came from frequency information and design.',limit='These historical bounds use a different architecture and target family from the current five-gas receiver.',notes='Standard atmosphere at 45°, charged 10 s reference plus 10 s sample, unknown noise and joint spectral nuisance. The prior six-output family differs from the current eight-output family. Do not use this table to rank current and old designs as equal conditions.',sources=['docs/45_payload_bounds_results.md'])
add('Task 4.2 · Time and calibration jointly set uncertainty',body=['Recomputed the link, absorption, emission and target fit when weather, elevation, bands or receiver noise change.','The latest common grid contains every VOC, PM2.5, coarse PM and PM10 in every operating condition.'],formula='C(t,σcal) = diag[Vsample(t/2) + Vreference(t/2)] + σcal²K\nKij = exp(−|νi − νj| / 10 GHz)',explain='Thermal variance decreases with retained symbols. The additional calibration residual persists through the acquisition.',result='More time helps until persistent calibration error dominates.',limit='The 10 GHz correlation length and each calibration standard deviation remain unmeasured assumptions.',sources=[GUIDE,'results/joint_receiver_revision/global_comparison_protocol.json'])
