add('Appendix · Low PM recalls remain visible',table=table,widths=[125,180,277,277,277],subtitle='Simulated recall, selected bands, standard atmosphere at 45°, same joint five-gas fit',limit='These recalls are near the false-alarm scale. No cell establishes useful PM detection.',notes=BASE+'. PM10 positive injection uses fine/coarse fractions 49/90 and 41/90. Each class has 10,000 trials. Binomial variation explains small nonmonotonic differences near the null rate. PM10 variance includes the cross covariance.',sources=['results/joint_receiver_revision/response_metrics.csv'],kind='dense')
add('Appendix · Reproducible evidence map',table=[['Research material','Repository location'],['Original task definition','I2R_proposal_THz_ISAC (1).pdf'],['Current results and global comparison','docs/51_joint_design_time_calibration_results.md'],['Species, equations and metric definitions','docs/50_species_methods_and_percentage_guide.md'],['Complete open-issue ledger','docs/49_completion_audit_and_fixes.md'],['Critical calibration record','docs/46_critical_calibration_assumption.md'],['Data, trials, hashes and validation','results/joint_receiver_revision/'],['Current manuscript','output/pdf/thz_isac_pollutant_sensing_ieee.pdf']],widths=[410,726],subtitle='Research snapshot 461a3ba, 27 September 2026',notes='Repository: https://github.com/unworthyzeus/THz_ISAC_atmospheric_monitoring . The snapshot contains 235 passing tests and 25,172 numerical checks. These counts describe the computational research snapshot, not slide validation or independent physical evidence.',sources=[AUDIT,CURRENT])
add('Appendix · Physical and methodological sources',body=['HITRAN2024 and HAPI: line data, isotope handling and spectroscopic calculations.','ITU-R P.835 and P.676: reference atmosphere, oxygen/water absorption and atmospheric background.','NOAA IGRA: independent measured weather soundings.','Aliaga et al. (2024) and Yang et al. (2024): satellite differential absorption and gas/particle propagation context.','Xu, Fu and Kim (2025): using pilots and payloads for sensing. Established M2M4 literature supplies the signal/noise estimator.'],limit='Published models motivate and parameterize the study. They do not validate this receiver’s field performance.',notes='Sources:\nHITRAN2024: https://hitran.org/media/refs/HITRAN-2024.pdf\nHAPI: https://doi.org/10.1016/j.jqsrt.2016.03.005\nITU-R P.835-7: https://www.itu.int/rec/R-REC-P.835\nITU-R P.676-13: https://www.itu.int/rec/R-REC-P.676\nNOAA IGRA: https://www.ncei.noaa.gov/products/weather-balloon/integrated-global-radiosonde-archive\nAliaga et al.: https://doi.org/10.1109/JSTARS.2024.3480816\nYang et al.: https://doi.org/10.1109/OJCOMS.2024.3386759\nXu et al.: https://arxiv.org/abs/2506.15998\nM2M4: Gianmarco Romano, 2021, doi:10.3390/s21154950. See full references in current manuscript.',sources=[PAPER])

